try
{
    LeapSeconds.StrictMode = false;
    var (offset, isStale) = TimeOffsets.SecondsUtcToTaiWithStale(farFuture);
    // assertions...
}
finally
{
    LeapSeconds.StrictMode = prevStrict;
}
```

